def gen(r):
    diff_label = r["diff"] + "\u96be\u5ea6"
    ings = "\n".join("      <div class=\"ingredient-item\">" + i + "</div>" for i in r["ingredients"])
    stps = "\n".join("      <div class=\"step\"><div class=\"step-num\">" + str(idx+1) + "</div><div class=\"step-text\">" + s + "</div></div>" for idx, s in enumerate(r["steps"]))
    return TEMPLATE.format(
        name=r["name"],
        region_full=r["regionFull"],
        desc=r["desc"],
        color=r["color"],
        color2=r["color2"],
        emoji=r["emoji"],
        diff_label=diff_label,
        time=r["time"],
        diff=r["diff"],
        ingredients=ings,
        steps=stps,
        tips=r["tips"]
    )

out = r"D:\AI\OpenCode\wangzhan\recipes"
os.makedirs(out, exist_ok=True)

for r in RECIPES:
    html = gen(r)
    fp = os.path.join(out, r["id"] + ".html")
    with open(fp, "w", encoding="utf-8") as f:
        f.write(html)
    print("Generated: " + r["id"] + ".html")

print("\nDone! Generated " + str(len(RECIPES)) + " recipe files.")
